#include <stdio.h>
#include <stdlib.h>

struct Node
{
    int roll;
    struct Node *next;
};

// Create a new node
struct Node* createNode(int roll)
{
    struct Node *newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->roll = roll;
    newNode->next = NULL;
    return newNode;
}

// Insert at end
void insert(struct Node **head, int roll)
{
    struct Node *newNode = createNode(roll);

    if (*head == NULL)
    {
        *head = newNode;
        return;
    }

    struct Node *temp = *head;

    while (temp->next != NULL)
        temp = temp->next;

    temp->next = newNode;
}

// Check whether roll number exists in a set
int search(struct Node *head, int roll)
{
    while (head != NULL)
    {
        if (head->roll == roll)
            return 1;

        head = head->next;
    }

    return 0;
}

// Display linked list
void display(struct Node *head)
{
    if (head == NULL)
    {
        printf("No students\n");
        return;
    }

    while (head != NULL)
    {
        printf("%d ", head->roll);
        head = head->next;
    }

    printf("\n");
}

int main()
{
    struct Node *A = NULL;
    struct Node *B = NULL;

    int nA, nB, roll, i;
    int neither = 0;

    // Input Set A
    printf("Enter number of students who like Vanilla: ");
    scanf("%d", &nA);

    printf("Enter roll numbers:\n");
    for (i = 0; i < nA; i++)
    {
        scanf("%d", &roll);
        insert(&A, roll);
